import sys

def _target(score):
    if score is None:
        return "unknown"
    if score >= 0.8:
        return "high"
    if score >= 0.5:
        return "medium"
    return "low"

def _strict_high(score):
    if score is None:
        return "unknown"
    if score > 0.8:
        return "high"
    if score >= 0.5:
        return "medium"
    return "low"

def _strict_medium(score):
    if score is None:
        return "unknown"
    if score >= 0.8:
        return "high"
    if score > 0.5:
        return "medium"
    return "low"

_RETURN_OFFSETS = {2, 4, 6, 7}

def _tests():
    return [v for k, v in sorted(globals().items()) if k.startswith("test_") and callable(v)]

def _call(test):
    marks = [m for m in getattr(test, "pytestmark", []) if m.name == "parametrize"]
    if not marks:
        test()
        return
    names, values = marks[0].args[0], marks[0].args[1]
    if isinstance(names, str):
        names = [n.strip() for n in names.split(",")]
    for value in values:
        value = getattr(value, "values", value)
        if not isinstance(value, (tuple, list)):
            value = (value,)
        test(**dict(zip(names, value)))

def _run_all(fn):
    globals()["risk_band"] = fn
    for test in _tests():
        _call(test)

def _lines_run():
    code = _target.__code__
    seen = set()

    def tracer(frame, event, arg):
        if frame.f_code is code:
            if event == "line":
                seen.add(frame.f_lineno - code.co_firstlineno)
            return tracer
        return None

    previous = sys.gettrace()
    sys.settrace(tracer)
    try:
        _run_all(_target)
    finally:
        sys.settrace(previous)
    return seen

def _some_test_fails(fn):
    try:
        _run_all(fn)
    except AssertionError:
        return True
    return False

exercises.prompt:
`risk_band(score)` is already imported in your test file:

```python
def risk_band(score: float | None) -> str:
    if score is None:
        return "unknown"
    if score >= 0.8:
        return "high"
    if score >= 0.5:
        return "medium"
    return "low"
```

Write tests, as functions whose names start with `test_`, that run every branch **and** catch an off-by-one change. The checker measures which lines your tests run, then runs them against two changed versions: `>= 0.8` becomes `> 0.8`, and `>= 0.5` becomes `> 0.5`. Your tests must fail for both.

exercises.solution:
import pytest


@pytest.mark.parametrize(
    ("score", "expected"),
    [
        pytest.param(None, "unknown", id="missing"),
        pytest.param(0.8, "high", id="at-0.8"),
        pytest.param(0.79, "medium", id="below-0.8"),
        pytest.param(0.5, "medium", id="at-0.5"),
        pytest.param(0.49, "low", id="below-0.5"),
    ],
)
def test_risk_band(score: float | None, expected: str) -> None:
    assert risk_band(score) == expected

